$ErrorActionPreference='Stop'
Set-Location -LiteralPath (Split-Path -Parent $PSScriptRoot)
$baseFull=@((Get-Content TestResults/courts-pulse-v0230-original-w10-pilot.json -Raw|ConvertFrom-Json).models)+@((Get-Content TestResults/courts-pulse-v0230-original-w10-remainder.json -Raw|ConvertFrom-Json).models)
$baseOpening=(Get-Content TestResults/courts-opening-v0230-w10.json -Raw|ConvertFrom-Json).models
