$pairs=@(foreach($row in $selected){
    $r=$row.result;$b=if($row.policy -eq 'opening'){@($baseOpening|Where-Object Seed -eq $r.Seed)[0]}else{@($baseFull|Where-Object {$_.Seed -eq $r.Seed -and $_.Policy -eq $row.policy})[0]}
    if($r.Spent -ne $b.Spent -or $r.Towers -ne $b.Towers -or $r.StartingCredits -ne 280 -or $r.State -ne 'Won' -or $r.Kills -ne 780 -or -not $r.AllSpawned -or $r.Remaining -ne 0){throw 'Selected paired budget/completion differs'}
