    $oldOrder=@($b.PurchaseLog|ForEach-Object {$_ -replace '^\d+\.\d+ ',''});$newOrder=@($r.PurchaseLog|ForEach-Object {$_ -replace '^\d+\.\d+ ',''})
    [ordered]@{seed=$r.Seed;policy=$row.policy;baseline=$b;candidate=$r;cardsSame=($b.Cards -join '/') -eq ($r.Cards -join '/');purchaseOrderSame=@(Compare-Object $oldOrder $newOrder -SyncWindow 0).Count -eq 0;purchaseTimesSame=($b.PurchaseLog -join '|') -eq ($r.PurchaseLog -join '|')}
})
foreach($candidate in @('speed115','speed125')){$scope=Get-Content ("TestResults/courts-heavy-v0230-$candidate-scope.json") -Raw|ConvertFrom-Json;if(-not $scope.auditPassed -or $scope.auditPending -or $scope.spawnStatCells -ne 840 -or $scope.changedSpeedStatCells -ne 6 -or $scope.actualAffectedLateHeavyEnemies -ne 19){throw 'Speed scope review differs'}}
